alter function private.candidate_push_timing_immutable_guard_v1() OWNER TO CURRENT_USER;
alter function public.candidate_push_timing_get_v1(jsonb) OWNER TO CURRENT_USER;
alter function public.candidate_push_timing_save_v1(jsonb) OWNER TO CURRENT_USER;
revoke all on function private.weekly_contact_assert_closed_v1(jsonb,text[],text[],text),
